import json
import numpy as np
from scipy import stats
from sklearn.metrics import f1_score

class NpEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, (np.bool_, bool)):
            return bool(obj)
        if isinstance(obj, np.integer):
            return int(obj)
        if isinstance(obj, np.floating):
            return float(obj)
        if isinstance(obj, np.ndarray):
            return obj.tolist()
        return super().default(obj)

dd = json.load(open('results/per_sample_predictions/dd_ood_per_sample.json'))
aa = json.load(open('results/per_sample_predictions/actorattack_per_sample.json'))

datasets = {'DD OOD Full': dd, 'ActorAttack Full': aa}
variants = ['9class', 'binary', 'scrambled', 'jb_mlm']
seeds = ['42', '123', '456']
pairs = [
    ('9class', 'scrambled'),
    ('9class', 'binary'),
    ('9class', 'jb_mlm'),
    ('scrambled', 'binary'),
]

f1_results = {}
print("=== Per-seed macro F1 ===")
for ds_name, ds_data in datasets.items():
    labels = ds_data['labels']
    f1_results[ds_name] = {}
    for var in variants:
        f1_results[ds_name][var] = {}
        for seed in seeds:
            preds = ds_data['preds'][var][seed]['full']
            f1 = f1_score(labels, preds, average='macro')
            f1_results[ds_name][var][seed] = float(f1)
        vals = [f1_results[ds_name][var][s] for s in seeds]
        print(f"  {ds_name} | {var:10s} | {vals[0]:.4f}  {vals[1]:.4f}  {vals[2]:.4f} | mean={np.mean(vals):.4f}")

def tost_equivalence(x, y, delta=0.05):
    diff = np.array(x) - np.array(y)
    n = len(diff)
    mean_diff = float(np.mean(diff))
    se = float(np.std(diff, ddof=1) / np.sqrt(n))
    if se == 0:
        within = abs(mean_diff) < delta
        return {
            'mean_diff': mean_diff, 'se': 0.0,
            'p_lower': 0.0 if within else 1.0,
            'p_upper': 0.0 if within else 1.0,
            'p_tost': 0.0 if within else 1.0,
            'ci_90': [mean_diff, mean_diff],
            'equivalent': within, 'ci_within_margin': within
        }
    t_lower = (mean_diff - (-delta)) / se
    t_upper = (delta - mean_diff) / se
    p_lower = float(stats.t.sf(t_lower, df=n-1))
    p_upper = float(stats.t.sf(t_upper, df=n-1))
    p_tost = max(p_lower, p_upper)
    t_crit = stats.t.ppf(0.95, df=n-1)
    ci_lower = mean_diff - t_crit * se
    ci_upper = mean_diff + t_crit * se
    return {
        'mean_diff': mean_diff, 'se': se,
        'p_lower': p_lower, 'p_upper': p_upper, 'p_tost': p_tost,
        'ci_90': [float(ci_lower), float(ci_upper)],
        'equivalent': bool(p_tost < 0.05),
        'ci_within_margin': bool(ci_lower >= -delta and ci_upper <= delta)
    }

results_table = []
print("\n=== TOST Results (delta=0.05) ===")
print(f"{'Comparison':<25s} | {'Dataset':<18s} | {'Mean Diff':>10s} | {'90% CI':>22s} | {'p_TOST':>8s} | CI in +/-0.05?")
print("-" * 110)

for v1, v2 in pairs:
    for ds_name in datasets:
        x = [f1_results[ds_name][v1][s] for s in seeds]
        y = [f1_results[ds_name][v2][s] for s in seeds]
        r = tost_equivalence(x, y, delta=0.05)
        ci_str = f"[{r['ci_90'][0]:+.4f}, {r['ci_90'][1]:+.4f}]"
        ci_ok = "Yes" if r['ci_within_margin'] else "No"
        comp = f"{v1} vs {v2}"
        print(f"{comp:<25s} | {ds_name:<18s} | {r['mean_diff']:+.4f}    | {ci_str:>22s} | {r['p_tost']:.4f}   | {ci_ok}")
        results_table.append({'comparison': comp, 'dataset': ds_name, **r})

output = {
    'method': 'TOST equivalence test (paired, seed-level macro F1)',
    'delta': 0.05,
    'seeds': seeds,
    'per_seed_f1': f1_results,
    'tost_results': results_table
}

with open('results/tost_equivalence.json', 'w') as f:
    json.dump(output, f, indent=2, cls=NpEncoder)
print("\nSaved to results/tost_equivalence.json")
